bookingEnd:
add_action( 'wp', function () {
	if ( ! current_user_can( 'manage_options' ) ) {
		show_admin_bar( false );
	}
} );

add_action('rest_api_init', function () {
    register_rest_route('eventi/v1', '/posti', array(
        'methods'  => 'GET',
        'callback' => 'get_posti_rimanenti_multi'
    ));
});

/**
 * Helper: base64 URL-safe
 */
function eventi_base64url_encode($data) {
    return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
}

/**
 * Ottiene un access token Google usando il service account
 */
function eventi_get_google_access_token() {
    static $cached = null;

    if ($cached && $cached['expires'] > time() + 60) {
        return $cached['access_token'];
    }

    // 🔴 MODIFICA QUESTO PERCORSO SE IL FILE È IN UN'ALTRA CARTELLA
    $json_path = ABSPATH . 'wp-content/keys/prenotazioni-eventi.json';

    if (!file_exists($json_path)) {
        return new WP_Error('no_json', 'File JSON service account non trovato: ' . $json_path);
    }

    $json = file_get_contents($json_path);
    $creds = json_decode($json, true);

    $private_key = $creds['private_key'];
    $client_email = $creds['client_email'];
    $token_uri = $creds['token_uri'];

    $now = time();

    $header = eventi_base64url_encode(json_encode([
        'alg' => 'RS256',
        'typ' => 'JWT',
    ]));

    $claim = eventi_base64url_encode(json_encode([
        'iss'   => $client_email,
        'scope' => 'https://www.googleapis.com/auth/spreadsheets.readonly',
        'aud'   => $token_uri,
        'iat'   => $now,
        'exp'   => $now + 3600,
    ]));

    $to_sign = $header . '.' . $claim;

    $signature = '';
    $ok = openssl_sign($to_sign, $signature, $private_key, 'sha256WithRSAEncryption');

    if (!$ok) {
        return new WP_Error('sign_error', 'Impossibile firmare il JWT');
    }

    $jwt = $to_sign . '.' . eventi_base64url_encode($signature);

    $response = wp_remote_post($token_uri, [
        'headers' => [
            'Content-Type' => 'application/x-www-form-urlencoded',
        ],
        'body' => [
            'grant_type' => 'urn:ietf:params:oauth:grant-type:jwt-bearer',
            'assertion'  => $jwt,
        ],
        'timeout' => 15,
    ]);

    if (is_wp_error($response)) {
        return $response;
    }

    $body = json_decode(wp_remote_retrieve_body($response), true);

    if (empty($body['access_token'])) {
        return new WP_Error('no_token', 'Nessun access_token ricevuto', $body);
    }

    $cached = [
        'access_token' => $body['access_token'],
        'expires'      => $now + intval($body['expires_in'] ?? 3600),
    ];

    return $cached['access_token'];
}

/**
 * REST callback: /wp-json/eventi/v1/posti?evento=1
 */
function get_posti_rimanenti_multi( $request ) {

    $evento = intval($request->get_param('evento'));
    if ($evento < 1) {
        return array('errore' => 'Parametro evento mancante o non valido (evento>=1)');
    }

    // Evento 1 → colonna B (2)
    // Evento 2 → colonna D (4)
    // Evento i → colonna = 2 + (i-1)*2
    $col_idx = 2 + ($evento - 1) * 2;

    // Gestiamo max 20 eventi → colonna fino a Z
    if ($col_idx > 26) {
        return array('errore' => 'Evento troppo grande, oltre colonna Z');
    }

    $letters = range('A', 'Z');
    $col_letter = $letters[$col_idx - 1];

    // Posti rimanenti alla riga 6
    $range = "FOGLIOCALCOLI!" . $col_letter . "6";

    $sheet_id = '1etWUd_uN9OoOLLWpijSM4ADLzjZfbpSnVOv547Zry90';

    // 🔹 Ottieni access token col service account
    $token = eventi_get_google_access_token();
    if (is_wp_error($token)) {
        return array('errore' => 'Errore token', 'dettaglio' => $token->get_error_message());
    }

    $url = "https://sheets.googleapis.com/v4/spreadsheets/$sheet_id/values/$range";

    $response = wp_remote_get($url, [
        'headers' => [
            'Authorization' => 'Bearer ' . $token,
        ],
        'timeout' => 15,
    ]);

    if (is_wp_error($response)) {
        return array('errore' => 'Foglio non accessibile', 'dettaglio' => $response->get_error_message());
    }

    $body = json_decode(wp_remote_retrieve_body($response), true);

    $raw = $body['values'][0][0] ?? '0';
    // Tieni solo cifre, nel dubbio
    $clean = preg_replace('/[^0-9]/', '', (string)$raw);
    $posti = intval($clean);

    return array(
        'evento'      => $evento,
        'colonna'     => $col_letter,
        'cella'       => $range,
        'raw'         => $raw,
        'clean'       => $clean,
        'disponibili' => $posti,
    );
}
